import type { ContentBlock } from "@/content/types";

type CodeBlockNode = Extract<ContentBlock, { type: "codeBlock" }>;

/**
 * Renders pre-highlighted HTML generated by the adapter's Shiki pass.
 *
 * `highlightedHtml` is a complete `<pre>` element produced at build time, so it
 * is injected verbatim. When it is absent (unknown language, empty code, or an
 * unbuilt adapter) the component falls back to escaped plain text.
 */
export function CodeBlock({ node }: { node: CodeBlockNode }) {
  if (node.highlightedHtml !== undefined && node.highlightedHtml !== "") {
    // Shiki output is generated from escaped source text at build time.
    return (
      <div
        className="my-8 overflow-x-auto rounded-md text-sm [&_pre]:m-0 [&_pre]:overflow-x-auto [&_pre]:p-4"
        dangerouslySetInnerHTML={{ __html: node.highlightedHtml }}
      />
    );
  }

  return (
    <pre className="my-8 overflow-x-auto rounded-md bg-muted/5 p-4 text-sm">
      <code className="font-mono text-fg">{node.code}</code>
    </pre>
  );
}
